window.AUTH=window.AUTH||{};window.AUTH["08-453"]={"d":"08-453","id":"2008/08-453","n":"Cuomo v. Clearing House Assn., L. L. C.","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the federal respondent","date":"","url":"https://www.justice.gov/osg/media/216331/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/cuomo-v-clearing-house-assn-brief-merits","n":72}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep557/usrep557519/usrep557519.pdf","tr":true,"items":[{"t":"case","label":"Altria Group, Inc. v. Good","cite":"129 S. Ct. 538","y":2008,"id":"2008/07-562","sc":1,"op":1,"sum":"The Court held that the Federal Cigarette Labeling and Advertising Act did not preempt all claims related to \"smoking and health\" under the Maine Unfair Trade Practices Act.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Anderson Nat’l Bank v. Luckett","cite":"321 U.S. 233","y":1944,"id":"scdb/1943-064","sc":1,"op":2,"sum":"A statute of Kentucky sets up a comprehensive scheme for the administration of abandoned bank deposits. Upon a report by the bank and notice to the depositor, and with an opportunity for either to be heard, the State takes into its protective custody bank accounts which, having been inactive for at least ten years if demand accounts or for at least twenty-five years if non-demand, the statute declares to be …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"52, 53"}},{"t":"case","label":"Barnett Bank, N.A. v. Nelson","cite":"517 U.S. 25","y":1996,"id":"1995/94-1837","sc":1,"op":2,"sum":"The Federal Statute pre-empts the State Statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Beneficial Nat’l Bank v. Anderson","cite":"539 U.S. 1","y":2003,"id":"2002/02-306","sc":1,"sum":"The Court held that the National Bank Act preempted the state-law claim and provided the exclusive cause of action for usury claims against national banks. Thus, the claim arose under federal law.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Buckman Co. v. Plaintiffs’ Legal Comm.","cite":"531 U.S. 341","y":2001,"id":"2000/98-1768","sc":1,"sum":"The Court held that the plaintiffs' state-law fraud-on-the-FDA claims conflicted with, and were therefore pre-empted by, the FDCA, as amended by the MDA. \"The conflict,\" wrote Chief Justice Rehnquist for the Court, \"stems from the fact that the federal statutory scheme amply empowers the FDA to punish and deter fraud against the Agency, and that this authority is used by the Agency to achieve a somewhat delicate balance of statutory objectives.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Capital Cities Cable, Inc. v. Crisp","cite":"467 U.S. 691","y":1984,"id":"1983/82-1795","sc":1,"sum":"The Court held unanimously that Oklahoma's ban on local cable transmissions of out-of-state alcoholic beverage commercials violated both the Supremacy and Commerce Clauses. While Oklahoma can regulate local cable aspects, such as franchise formation and construction, it cannot tamper with the flow of information from other states.","sumSrc":"Oyez","by":{"0":"6, 15, 16"}},{"t":"case","label":"Citizens Bank v. Alafabco, Inc.","cite":"539 U.S. 52","y":2003,"id":"2002/02-1295","sc":1,"sum":"The Court held that the parties’ debt-restructuring agreement affected interstate commerce, and therefore their arbitration clause was enforceable under the Federal Arbitration Act.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"City of N.Y. v. FCC","cite":"486 U.S. 57","y":1988,"id":"1987/87-339","sc":1,"sum":"The FCC did not exceed its statutory authority by forbidding local authorities to impose technical cable signal quality standards more stringent than those set forth in the Commission's regulations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10, 22, 24"}},{"t":"case","label":"Clarke v. Securities Indus. Ass’n","cite":"479 U.S. 388","y":1987,"id":"1986/85-971","sc":1,"sum":"Petitioner Security Pacific National Bank (Security Pacific) applied to the Comptroller of the Currency for permission to establish an affiliate named Discount Brokerage, and to offer discount brokerage services not only at its branch offices but also at other locations inside and outside of its home State. A pertinent branching provision of the National Bank Act, 12 U. S. C. § 81, originally enacted in 1927 as part …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Davis v. Elmira Sav. Bank","cite":"161 U.S. 275","y":1896,"id":"scdb/1895-136","sc":1,"sum":"Section 130 of chapter 689 of the laws of New York of 1892, providing for the payment by the receiver of an insolvent bank, in the first place, of deposits in the bank by savings banks, when applied to an insolvent national bank, is in conflict with § 5236 of the Revised Statutes of the United States, directing the Comptroller of the Currency to make ratable dividends of the money paid over to him by such receiver, …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"13, 17"}},{"t":"case","label":"Easton v. Iowa","cite":"188 U.S. 220","y":1903,"id":"scdb/1902-051","sc":1,"op":1,"ar":1,"sum":"Congress having power to create a system of national banks, is the judge as to the extent of the powers which should he conferred upon such banks, and has the sole power to regulate and control the exercise of their operations. Congress having dealt directly with the insolvency of national banks by giving control to the Secretary of the Treasury and the Comptroller of the Currency, who are authorized to suspendthe …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"39, 41"}},{"t":"case","label":"Farmers’ & Mechs’. Nat’l Bank v. Dearing","cite":"91 U.S. 29","y":1875,"id":"scdb/1875-007","sc":1,"op":1,"by":{"0":"7, 13, 17"}},{"t":"case","label":"Fidelity Fed. Sav. & Loan Ass’n v. de la Cuesta","cite":"458 U.S. 141","y":1982,"id":"1981/81-750","sc":1,"sum":"The Board's due-on-sale regulation pre-empts conflicting state limitations on the due-on-sale practices of federal savings and loan associations, and thus bars application of the Wellenkamp rule to such associations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10, 22"}},{"t":"case","label":"First Nat’l Bank v. Hughes","cite":"6 F. 737","y":1881,"court":"C.C.N.D. Ohio","url":"https://www.courtlistener.com/c/F./6/737/","op":1,"by":{"0":"51"}},{"t":"case","label":"First Nat’l Bank in Plant City v. Dickinson","cite":"396 U.S. 122","y":1969,"id":"1969/19","sc":1,"op":1,"sum":"Petitioner in No. 19, a national bank in Florida, having been granted permission by the Comptroller of the Currency of the United States, operated two off-premises services. (1) The bank operated an armored car (a \"mobile drive-in\"), equipped with a glass window and customer's service counter and staffed by a driverguard and teller (both bank employees). The armored car delivered cash in exchange for checks and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 35, 50, 51"}},{"t":"case","label":"First Nat’l Bank in St. Louis v. Missouri","cite":"263 U.S. 640","y":1924,"id":"scdb/1923-214","sc":1,"op":7,"sum":"1. National banks are subject to state laws that do not interfere with the purposes of their creation, tend to destroy or impair their efficiency as federal agencies, of conflict with the laws of the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"51, 52"}},{"t":"case","label":"First Nat’l Bank of Bay City v. Fellows","cite":"244 U.S. 416","y":1917,"id":"scdb/1916-102","sc":1,"op":1,"sum":"By the principles fully settled in McCulloch v. Maryland and Osborn v. Bank, and other cases, the implied power of Congress to confer a particular function upon a national bank is to be tested, not by the nature of the function viewed by itself, but by its relations to all the functions, and attributes of the bank considered as an entity; the necessity or appropriateness of the function should be considered with …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"First Union Nat’l Bank v. Burke","cite":"48 F. Supp. 2d 132","y":1999,"court":"D. Conn.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/48/132/","by":{"0":"7, 11, 38, 39, 43, 44"}},{"t":"case","label":"Guthrie v. Harkness","cite":"199 U.S. 148","y":1905,"id":"scdb/1905-027","sc":1,"op":5,"ar":4,"sum":"States have no power to enact legislation contravening Federal laws for the control of national banks, but such banks are, for actions against them at law or in equity, deemed citizens of the States in which they are located, and the Federal courts have such jurisdiction only as they have in cases between individual citizens of the same States.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Hines v. Davidowitz","cite":"312 U.S. 52","y":1941,"id":"scdb/1940-064","sc":1,"sum":"1. Applicable legislation enacted while the case was pending on appeal will be enforced by the appellate court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Investment Co. Inst. v. Camp","cite":"401 U.S. 617","y":1971,"id":"1970/61","sc":1,"sum":"Petitioners in No. 61, an association of open-end investment companies and several individual such companies, attack (1) portions of the Comptroller of the Currency's Regulation 9, purporting to authorize banks to operate collective investment funds, as violative of the Glass-Steagall Banking Act of 1933 and (2) the Comptroller's approval given First National City Bank to operate a collective investment fund. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"McCulloch v. Maryland","cite":"17 U.S. 316","y":1819,"id":"1789-1850/17us316","sc":1,"op":1,"ar":2,"sum":"The Court decided that the Second Bank of the United States could not be taxed by the state of Maryland, declaring that the government of individual states cannot impose laws on the functioning of the federal government.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Mississippi Power & Light Co. v. Mississippi ex rel. Moore","cite":"487 U.S. 354","y":1988,"id":"1987/86-1970","sc":1,"op":1,"sum":"The FERC proceedings pre-empted a prudence inquiry by the MPSC. The decision in Nantahalarests on a foundation that is broad enough to support the order entered by FERC here and to require the MPSC to treat appellant's FERC-mandated payments for Grand Gulf costs as reasonably incurred operating expenses for the purpose of setting appellant's retail rates. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"NationsBank v. Variable Annuity Life Ins. Co.","cite":"513 U.S. 251","y":1995,"id":"1994/93-1612","sc":1,"op":1,"sum":"Petitioner national bank and its brokerage subsidiary applied to the Comptroller of the Currency, charged by Congress with superintendence of national banks, to allow the subsidiary to act as an agent in the sale of annuities. Under the proposed plan, bank customers could purchase a \"variable annuity\"-which invests payments in a designated way and yields income that varies with investment performance-a \"fixed\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 17, 25"}},{"t":"case","label":"National Bank v. Kentucky","cite":"76 U.S. 353","y":1870,"id":"scdb/1869-077","sc":1,"sum":"The act of Congress establishing the National banks, enacts:","sumSrc":"Headnote (U.S. Reports)","by":{"0":"51"}},{"t":"case","label":"National Cable & Telecomms. Ass’n v. Brand X Internet Serv.","cite":"545 U.S. 967","y":2005,"id":"2004/04-277","sc":1,"op":3,"sum":"The Court held that the FCC lawfully construed the Communications Act to not define cable broadband providers as \"telecommunications services.\" The Court held that the Ninth Circuit should have followed the Supreme Court's 1984 decision in Chevron v. Natural Resources Defense Council.","sumSrc":"Oyez","by":{"0":"26, 50"}},{"t":"case","label":"National State Bank v. Long","cite":"630 F.2d 981","y":1980,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/630/981/","by":{"0":"54"}},{"t":"case","label":"New York v. FERC","cite":"535 U.S. 1","y":2002,"id":"2001/00-568","sc":1,"sum":"The Court held that FERC properly construed its statutory authority.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"sum":"The Court upheld two of the three provisions of the Act under review, reasoning that Congress had the authority under the Commerce Clause to use financial rewards and access to disposal sites as incentives for state waste management.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"sum":"The Court held that Congress could not require state agencies to perform federal duties under the Necessary and Proper Clause.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Smiley v. Citibank (South Dakota), N.A.","cite":"517 U.S. 735","y":1996,"id":"1995/95-860","sc":1,"op":3,"ar":2,"sum":"The Court held that the National Bank Act of 1864 authorizes such charges because a regulation adopted by the Comptroller of the Currency, which defined interest to include late-payment fees, was a reasonable interpretation of the act and entitled to deference.","sumSrc":"Oyez","by":{"0":"9, 10, 21, 28"}},{"t":"case","label":"Talbott v. Silver Bow County","cite":"139 U.S. 438","y":1891,"id":"scdb/1890-186","sc":1,"sum":"The territories possess the same power of taxing national banks which States enjoy.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Tiffany v. National Bank","cite":"85 U.S. 409","y":1874,"id":"scdb/1873-091","sc":1,"sum":"Tiffany, trustee of Darby, a bankrupt, brought an action of debt iti the court below against the National.Bank of Missouri, a corporation organized under the National Banking Act of June 3d, 1864, to recover under the provisions of the 'thirtieth section of the act twice the amount of interest paid by the said Darby, on certain loans made by the bank to him before he was adjudged a bankrupt. The ground of the action …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"2, 13, 40"}},{"t":"case","label":"Trustees of Dartmouth Coll. v. Woodward","cite":"17 U.S. 518","y":1819,"id":"1789-1850/17us518","sc":1,"op":3,"sum":"The Court held that the charter to Dartmouth College was a contract between private parties, and that the New Hampshire government's attempt to turn the College into a public institution was unconstitutional under the contract clause.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"United States v. Locke","cite":"529 U.S. 89","y":2000,"id":"1999/98-1701","sc":1,"op":3,"sum":"The Court held that Washington's regulations regarding general navigation watch procedures, crew English-language skills and training, and maritime casualty reporting are pre-empted by the comprehensive federal regulatory scheme governing oil tankers. \"The State of Washington has enacted legislation in an area where the federal interest has been manifest since the beginning of our Republic and is now well established,\" wrote Justice Kennedy for the Court.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"op":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"0":"16, 26"}},{"t":"case","label":"United States v. Philadelphia Nat’l Bank","cite":"374 U.S. 321","y":1963,"id":"1962/83","sc":1,"sum":"The proposed consolidation of appellee banks is forbidden by § 7 of the Clayton Act, and it must be enjoined.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"54"}},{"t":"case","label":"Waite v. Dowley","cite":"94 U.S. 527","y":1877,"id":"scdb/1876-165","sc":1,"op":1,"sum":"On the 9th of November, 1865, the legislature of Vermont-passed the following act. Acts of 1865, p. 17.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"51"}},{"t":"case","label":"Watters v. Wachovia Bank, N.A.","cite":"550 U.S. 1","y":2007,"id":"2006/05-1342","sc":1,"op":9,"ar":6,"sum":"Describing §§ 445.1661 and 493.56b as “state visitorial oversight”.","sumSrc":"opinion","by":{"0":"passim"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","by":{"0":"5"}},{"t":"usc","label":"15 U.S.C. § 1691","url":"https://www.law.cornell.edu/uscode/text/15/1691","subs":["(g)"],"by":{"0":"3, 54, 4"}},{"t":"usc","label":"15 U.S.C. § 1691e","url":"https://www.law.cornell.edu/uscode/text/15/1691e","subs":["(k)"],"by":{"0":"4"}},{"t":"usc","label":"42 U.S.C. § 3601","url":"https://www.law.cornell.edu/uscode/text/42/3601","by":{"0":"3"}},{"t":"usc","label":"42 U.S.C. § 3610","url":"https://www.law.cornell.edu/uscode/text/42/3610","subs":["(f)"],"by":{"0":"37, 37"}},{"t":"usc","label":"42 U.S.C. § 3614","url":"https://www.law.cornell.edu/uscode/text/42/3614","by":{"0":"37"}},{"t":"usc","label":"12 U.S.C. § 2801","url":"https://www.law.cornell.edu/uscode/text/12/2801","by":{"0":"3"}},{"t":"usc","label":"12 U.S.C. § 2803","url":"https://www.law.cornell.edu/uscode/text/12/2803","by":{"0":"4"}},{"t":"usc","label":"12 U.S.C. § 21","url":"https://www.law.cornell.edu/uscode/text/12/21","by":{"0":"2"}},{"t":"usc","label":"12 U.S.C. § 24","url":"https://www.law.cornell.edu/uscode/text/12/24","stext":{"head":"§24. Corporate powers of associations","paras":[[0,"Upon duly making and filing articles of association and an organization certificate a national banking association shall become, as from the date of the execution of its organization certificate, a body corporate, and as such, and in the name designated in the organization certificate, it shall have power—"],[0,"First. To adopt and use a corporate seal."],[0,"Second. To have succession from February 25, 1927, or from the date of its organization if organized after February 25, 1927, until such time as it be dissolved by the act of its shareholders owning two-thirds of its stock, or until its franchise becomes forfeited by reason of violation of law, or until terminated by either a general or a special Act of Congress or until its affairs be placed in the hands of a receiver and finally wound up by him."],[0,"Third. To make contracts."],[0,"Fourth. To sue and be sued, complain and defend, in any court of law and equity, as fully as natural persons."],[0,"Fifth. To elect or appoint directors, and by its board of directors to appoint a president, vice president, cashier, and other officers, define their duties, require bonds of them and fix the penalty thereof, dismiss such officers or any of them at pleasure, and appoint others to fill their places."],[0,"Sixth. To prescribe, by its board of directors, bylaws not inconsistent with law, regulating the manner in which its stock shall be transferred, its directors elected or appointed, its officers appointed, its property transferred, its general business conducted, and the privileges granted to it by law exercised and enjoyed."],[0,"Seventh. To exercise by its board of directors or duly authorized officers or agents, subject to law, all such incidental powers as shall be necessary to carry on the business of banking; by discounting and negotiating promissory notes, drafts, bills of exchange, and other evidences of debt; by receiving deposits; by buying and selling exchange, coin, and bullion; by loaning money on personal security; and by obtaining, issuing, and circulating notes according to the provisions of title 62 of the Revised Statutes. The business of dealing in securities and stock by the association shall be limited to purchasing and selling such securities and stock without recourse, solely upon the order, and for the account of, customers, and in no case for its own account, and the association shall not underwrite any issue of securities or stock; Provided, That the association may purchase for its own account investment securities under such limitations and restrictions as the Comptroller of the Currency may by regulation prescribe. In no event shall the total amount of the investment securities of any one obligor or maker, held by the association for its own account, exceed at any time 10 per centum of its capital stock actually paid in and unimpaired and 10 per centum of its unimpaired surplus fund, except that this limitation shall not require any association to dispose of any securities lawfully held by it on August 23, 1935. As used in this section the term \"investment securities\" shall mean marketable obligations, evidencing indebtedness of any person, copartnership, association, or corporation in the form of bonds, notes and/or debentures commonly known as investment securities under such further definition of the term \"investment securities\" as may by regulation be prescribed by the Comptroller of the Currency. Except as hereinafter provided or otherwise permitted by law, nothing herein contained shall authorize the purchase by the association for its own account of any shares of stock of any corporation. The limitations and restrictions herein contained as to dealing in, underwriting and purchasing for its own account, investment securities shall not apply to obligations of the United States, or general obligations of any State or of any political subdivision thereof, or obligations of the Washington Metropolitan Area Transit Authority which are guaranteed by the Secretary of Transportation under section 9 of the National Capital Transportation Act of 1969, or obligations issued under authority of the Federal Farm Loan Act, as amended, or issued by the thirteen banks for cooperatives or any of them or the Federal Home Loan Banks, or obligations which are insured by the Secretary of Housing and Urban Development under title XI of the National Housing Act [12 U.S.C. 1749aaa et seq.] or obligations which are insured by the Secretary of Housing and Urban Development (hereinafter in this sentence referred to as the \"Secretary\") pursuant to section 207 of the National Housing Act [12 U.S.C. 1713], if the debentures to be issued in payment of such insured obligations are guaranteed as to principal and interest by the United States, or obligations, participations, or other instruments of or issued by the Federal National Mortgage Association, or the Government National Mortgage Association, or mortgages, obligations or other securities which are or ever have been sold by the Federal Home Loan Mortgage Corporation pursuant to section 305 or section 306 of the Federal Home Loan Mortgage Corporation Act [12 U.S.C. 1454 or 1455], or obligations of the Federal Financing Bank or obligations of the Environmental Financing Authority, or obligations or other instruments or securities of the Student Loan Marketing Association, or such obligations of any local public agency (as defined in section 110(h) of the Housing Act of 1949 [42 U.S.C. 1460(h)]) as are secured by an agreement between the local public agency and the Secretary in which the local public agency agrees to borrow from said Secretary, and said Secretary agrees to lend to said local public agency, monies in an aggregate amount which (together with any other monies irrevocably committed to the payment of interest on such obligations) will suffice to pay, when due, the interest on and all installments (including the final installment) of the principal of such obligations, which monies under the terms of said agreement are required to be used for such payments, or such obligations of a public housing agency (as defined in the United States Housing Act of 1937, as amended [42 U.S.C. 1437 et seq.]) as are secured (1) by an agreement between the public housing agency and the Secretary in which the public housing agency agrees to borrow from the Secretary, and the Secretary agrees to lend to the public housing agency, prior to the maturity of such obligations, monies in an amount which (together with any other monies irrevocably committed to the payment of interest on such obligations) will suffice to pay the principal of such obligations with interest to maturity thereon, which monies under the terms of said agreement are required to be used for the purpose of paying the principal of and the interest on such obligations at their maturity, (2) by a pledge of annual contributions under an annual contributions contract between such public housing agency and the Secretary if such contract shall contain the covenant by the Secretary which is authorized by subsection (g) of section 6 of the United States Housing Act of 1937, as amended [42 U.S.C. 1437d(g)], and if the maximum sum and the maximum period specified in such contract pursuant to said subsection 6(g) [42 U.S.C. 1437d(g)] shall not be less than the annual amount and the period for payment which are requisite to provide for the payment when due of all installments of principal and interest on such obligations, or (3) by a pledge of both annual contributions under an annual contributions contract containing the covenant by the Secretary which is authorized by section 6(g) of the United States Housing Act of 1937 [42 U.S.C. 1437d(g)], and a loan under an agreement between the local public housing agency and the Secretary in which the public housing agency agrees to borrow from the Secretary, and the Secretary agrees to lend to the public housing agency, prior to the maturity of the obligations involved, moneys in an amount which (together with any other moneys irrevocably committed under the annual contributions contract to the payment of principal and interest on such obligations) will suffice to provide for the payment when due of all installments of principal and interest on such obligations, which moneys under the terms of the agreement are required to be used for the purpose of paying the principal and interest on such obligations at their maturity: Provided, That in carrying on the business commonly known as the safe-deposit business the association shall not invest in the capital stock of a corporation organized under the law of any State to conduct a safe-deposit business in an amount in excess of 15 per centum of the capital stock of the association actually paid in and unimpaired and 15 per centum of its unimpaired surplus. The limitations and restrictions herein contained as to dealing in and underwriting investment securities shall not apply to obligations issued by the International Bank for Reconstruction and Development, the European Bank for Reconstruction and Development, the Inter-American Development Bank 1 Bank for Economic Cooperation and Development in the Middle East and North Africa,,2 the North American Development Bank, the Asian Development Bank, the African Development Bank, the Inter-American Investment Corporation, or the International Finance Corporation,,2 or obligations issued by any State or political subdivision or any agency of a State or political subdivision for housing, university, or dormitory purposes, which are at the time eligible for purchase by a national bank for its own account, nor to bonds, notes and other obligations issued by the Tennessee Valley Authority or by the United States Postal Service: Provided, That no association shall hold obligations issued by any of said organizations as a result of underwriting, dealing, or purchasing for its own account (and for this purpose obligations as to which it is under commitment shall be deemed to be held by it) in a total amount exceeding at any one time 10 per centum of its capital stock actually paid in and unimpaired and 10 per centum of its unimpaired surplus fund. Notwithstanding any other provision in this paragraph, the association may purchase for its own account shares of stock issued by a corporation authorized to be created pursuant to title IX of the Housing and Urban Development Act of 1968 [42 U.S.C. 3931 et seq.], and may make investments in a partnership, limited partnership, or joint venture formed pursuant to section 907(a) or 907(c) of that Act [42 U.S.C. 3937(a) or 3937(c)]. Notwithstanding any other provision of this paragraph, the association may purchase for its own account shares of stock issued by any State housing corporation incorporated in the State in which the association is located and may make investments in loans and commitments for loans to any such corporation: Provided, That in no event shall the total amount of such stock held for its own account and such investments in loans and commitments made by the association exceed at any time 5 per centum of its capital stock actually paid in and unimpaired plus 5 per centum of its unimpaired surplus fund. Notwithstanding any other provision in this paragraph, the association may purchase for its own account shares of stock issued by a corporation organized solely for the purpose of making loans to farmers and ranchers for agricultural purposes, including the breeding, raising, fattening, or marketing of livestock. However, unless the association owns at least 80 per centum of the stock of such agricultural credit corporation the amount invested by the association at any one time in the stock of such corporation shall not exceed 20 per centum of the unimpaired capital and surplus of the association: Provided further, That notwithstanding any other provision of this paragraph, the association may purchase for its own account shares of stock of a bank insured by the Federal Deposit Insurance Corporation or a holding company which owns or controls such an insured bank if the stock of such bank or company is owned exclusively (except to the extent directors' qualifying shares are required by law) by depository institutions or depository institution holding companies (as defined in section 1813 of this title) and such bank or company and all subsidiaries thereof are engaged exclusively in providing services to or for other depository institutions, their holding companies, and the officers, directors, and employees of such institutions and companies, and in providing correspondent banking services at the request of other depository institutions or their holding companies (also referred to as a \"banker's bank\"), but in no event shall the total amount of such stock held by the association in any bank or holding company exceed at any time 10 per centum of the association's capital stock and paid in and unimpaired surplus and in no event shall the purchase of such stock result in an association's acquiring more than 5 per centum of any class of voting securities of such bank or company. The limitations and restrictions contained in this paragraph as to an association purchasing for its own account investment securities shall not apply to securities that (A) are offered and sold pursuant to section 4(5) of the Securities Act of 1933 (15 U.S.C. 77d(5)); 3 (B) are small business related securities (as defined in section 3(a)(53) of the Securities Exchange Act of 1934 [15 U.S.C. 78c(a)(53)]); or (C) are mortgage related securities (as that term is defined in section 3(a)(41) of the Securities Exchange Act of 1934 (15 U.S.C. 78c(a)(41)).4 The exception provided for the securities described in subparagraphs (A), (B), and (C) shall be subject to such regulations as the Comptroller of the Currency may prescribe, including regulations prescribing minimum size of the issue (at the time of initial distribution) or minimum aggregate sales prices, or both."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/24?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§24. Corporate powers of associations","tname":"Banks and Banking","by":{"0":"49"}},{"t":"usc","label":"12 U.S.C. § 62","url":"https://www.law.cornell.edu/uscode/text/12/62","stext":{"head":"§62. List of shareholders","paras":[[0,"The president and cashier of every national banking association shall cause to be kept at all times a full and correct list of the names and residences of all the shareholders in the association, and the number of shares held by each, in the office where its business is transacted. Such list shall be subject to the inspection of all the shareholders and creditors of the association, and the officers authorized to assess taxes under State authority, during business hours of each day in which business may be legally transacted. A copy of such list, verified by the oath of such president or cashier, shall be transmitted to the Comptroller of the Currency within ten days of any demand therefor made by him."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/62?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§62. List of shareholders","tname":"Banks and Banking","by":{"0":"36"}},{"t":"usc","label":"12 U.S.C. § 85","url":"https://www.law.cornell.edu/uscode/text/12/85","stext":{"head":"§85. Rate of interest on loans, discounts and purchases","paras":[[0,"Any association may take, receive, reserve, and charge on any loan or discount made, or upon any notes, bills of exchange, or other evidences of debt, interest at the rate allowed by the laws of the State, Territory, or District where the bank is located, or at a rate of 1 per centum in excess of the discount rate on ninety-day commercial paper in effect at the Federal reserve bank in the Federal reserve district where the bank is located, whichever may be the greater, and no more, except that where by the laws of any State a different rate is limited for banks organized under State laws, the rate so limited shall be allowed for associations organized or existing in any such State under title 62 of the Revised Statutes. When no rate is fixed by the laws of the State, or Territory, or District, the bank may take, receive, reserve, or charge a rate not exceeding 7 per centum, or 1 per centum in excess of the discount rate on ninety day commercial paper in effect at the Federal reserve bank in the Federal reserve district where the bank is located, whichever may be the greater, and such interest may be taken in advance, reckoning the days for which the note, bill, or other evidence of debt has to run. The maximum amount of interest or discount to be charged at a branch of an association located outside of the States of the United States and the District of Columbia shall be at the rate allowed by the laws of the country, territory, dependency, province, dominion, insular possession, or other political subdivision where the branch is located. And the purchase, discount, or sale of a bona fide bill of exchange, payable at another place than the place of such purchase, discount, or sale, at not more than the current rate of exchange for sight drafts in addition to the interest, shall not be considered as taking or receiving a greater rate of interest."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/85?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§85. Rate of interest on loans, discounts and purchases","tname":"Banks and Banking","by":{"0":"21, 40"}},{"t":"usc","label":"12 U.S.C. § 93a","url":"https://www.law.cornell.edu/uscode/text/12/93a","by":{"0":"49"}},{"t":"usc","label":"12 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/12/371","subs":["(a)"],"stext":{"head":"§371. Real estate loans","paras":[[0,"(a) Authorization to make real estate loans; orders, rules, and regulations of Comptroller of the Currency"],[0,"Any national banking association may make, arrange, purchase or sell loans or extensions of credit secured by liens on interests in real estate, subject to section 1828(o) of this title and such restrictions and requirements as the Comptroller of the Currency may prescribe by regulation or order."],[0,"(b) Eligibility for discount as commercial paper of notes representing loans financing construction of residential or farm buildings; prerequisites"],[0,"Notes representing loans made under this section to finance the construction of residential or farm buildings and having maturities not to exceed nine months shall be eligible for discount as commercial paper within the terms of the first paragraph of section 343 of this title if accompanied by a valid and binding agreement to advance the full amount of the loan upon the completion of the building entered into by an individual, partnership, association, or corporation acceptable to the discounting bank."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/371?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§371. Real estate loans","tname":"Banks and Banking","by":{"0":"49"}},{"t":"usc","label":"12 U.S.C. § 484","url":"https://www.law.cornell.edu/uscode/text/12/484","subs":["(a)","(b)"],"stext":{"head":"§484. Limitation on visitorial powers","paras":[[0,"(a) No national bank shall be subject to any visitorial powers except as authorized by Federal law, vested in the courts of justice or such as shall be, or have been exercised or directed by Congress or by either House thereof or by any committee of Congress or of either House duly authorized."],[0,"(b) Notwithstanding subsection (a), lawfully authorized State auditors and examiners may, at reasonable times and upon reasonable notice to a bank, review its records solely to ensure compliance with applicable State unclaimed property or escheat laws upon reasonable cause to believe that the bank has failed to comply with such laws."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/484?type=usc&year=mostrecent&link-type=html"},"op":8,"ar":2,"head":"§484. Limitation on visitorial powers","tname":"Banks and Banking","by":{"0":"passim, 2, 3, 9, 14, 35, 36, 37, 2, 14, 35, 36, 53"}},{"t":"law","label":"Pub. L. No. 103-328","url":"https://www.govinfo.gov/link/statute/108/2338","by":{"0":"46"}},{"t":"usc","label":"12 U.S.C. § 36","url":"https://www.law.cornell.edu/uscode/text/12/36","subs":["(1970)","(f)(1)(A)","(f)(1)(B)","(f)(3)"],"stext":{"head":"§36. Branch banks","paras":[[0,"The conditions upon which a national banking association may retain or establish and operate a branch or branches are the following:"],[0,"(a) Lawful and continuous operation"],[0,"A national banking association may retain and operate such branch or branches as it may have had in lawful operation on February 25, 1927, and any national banking association which continuously maintained and operated not more than one branch for a period of more than twenty-five years immediately preceding February 25, 1927, may continue to maintain and operate such branch."],[0,"(b) Converted State banks"],[0,"(1) A national bank resulting from the conversion of a State bank may retain and operate as a branch any office which was a branch of the State bank immediately prior to conversion if such office—"],[1,"(A) might be established under subsection (c) of this section as a new branch of the resulting national bank, and is approved by the Comptroller of the Currency for continued operation as a branch of the resulting national bank;"],[1,"(B) was a branch of any bank on February 25, 1927; or"],[1,"(C) is approved by the Comptroller of the Currency for continued operation as a branch of the resulting national bank."],[0,"The Comptroller of the Currency may not grant approval under clause (C) of this paragraph if a State bank (in a situation identical to that of the national bank) resulting from the conversion of a national bank would be prohibited by the law of such State from retaining and operating as a branch an identically situated office which was a branch of the national bank immediately prior to conversion."],[0,"(2) A national bank (referred to in this paragraph as the \"resulting bank\"), resulting from the consolidation of a national bank (referred to in this paragraph as the \"national bank\") under whose charter the consolidation is effected with another bank or banks, may retain and operate as a branch any office which, immediately prior to such consolidation, was in operation as—"],[1,"(A) a main office or branch office of any bank (other than the national bank) participating in the consolidation if, under subsection (c) of this section, it might be established as a new branch of the resulting bank, and if the Comptroller of the Currency approves of its continued operation after the consolidation;"],[1,"(B) a branch of any bank participating in the consolidation, and which, on February 25, 1927, was in operation as a branch of any bank; or"],[1,"(C) a branch of the national bank and which, on February 25, 1927, was not in operation as a branch of any bank, if the Comptroller of the Currency approves of its continued operation after the consolidation."],[0,"The Comptroller of the Currency may not grant approval under clause (C) of this paragraph if a State bank (in a situation identical to that of the resulting national bank) resulting from the consolidation into a State bank of another bank or banks would be prohibited by the law of such State from retaining and operating as a branch an identically situated office which was a branch of the State bank immediately prior to consolidation."],[0,"(3) As used in this subsection, the term \"consolidation\" includes a merger."],[0,"(c) New branches"],[0,"A national banking association may, with the approval of the Comptroller of the Currency, establish and operate new branches: (1) Within the limits of the city, town or village in which said association is situated, if such establishment and operation are at the time expressly authorized to State banks by the law of the State in question; and (2) at any point within the State in which said association is situated, if such establishment and operation are at the time authorized to State banks by the statute law of the State in question by language specifically granting such authority affirmatively and not merely by implication or recognition, and subject to the restrictions as to location imposed by the law of the State on State banks. In any State in which State banks are permitted by statute law to maintain branches within county or greater limits, if no bank is located and doing business in the place where the proposed agency is to be located, any national banking association situated in such State may, with the approval of the Comptroller of the Currency, establish and operate, without regard to the capital requirements of this section, a seasonal agency in any resort community within the limits of the county in which the main office of such association is located, for the purpose of receiving and paying out deposits, issuing and cashing checks and drafts, and doing business incident thereto: Provided, That any permit issued under this sentence shall be revoked upon the opening of a State or national bank in such community. Except as provided in the immediately preceding sentence, no such association shall establish a branch outside of the city, town, or village in which it is situated unless it has a combined capital stock and surplus equal to the combined amount of capital stock and surplus, if any, required by the law of the State in which such association is situated for the establishment of such branches by State banks, or, if the law of such State requires only a minimum capital stock for the establishment of such branches by State banks, unless such association has not less than an equal amount of capital stock."],[0,"(d) Branches resulting from interstate merger transactions"],[0,"A national bank resulting from an interstate merger transaction (as defined in section 1831u(f)(6) 1 of this title) may maintain and operate a branch in a State other than the home State (as defined in subsection (g)(3)(B)) of such bank in accordance with section 1831u of this title."],[0,"(e) Exclusive authority for additional branches"],[0,"(1) In general"],[1,"Effective June 1, 1997, a national bank may not acquire, establish, or operate a branch in any State other than the bank's home State (as defined in subsection (g)(3)(B)) or a State in which the bank already has a branch unless the acquisition, establishment, or operation of such branch in such State by such national bank is authorized under this section or section 1823(f), 1823(k), or 1831u of this title."],[0,"(2) Retention of branches"],[1,"In the case of a national bank which relocates the main office of such bank from 1 State to another State after May 31, 1997, the bank may retain and operate branches within the State which was the bank's home State (as defined in subsection (g)(3)(B)) before the relocation of such office only to the extent the bank would be authorized, under this section or any other provision of law referred to in paragraph (1), to acquire, establish, or commence to operate a branch in such State if—"],[2,"(A) the bank had no branches in such State; or"],[2,"(B) the branch resulted from—"],[3,"(i) an interstate merger transaction approved pursuant to section 1831u of this title; or"],[3,"(ii) a transaction after May 31, 1997, pursuant to which the bank received assistance from the Federal Deposit Insurance Corporation under section 1823(c) of this title."],[0,"(f) Law applicable to interstate branching operations"],[0,"(1) Law applicable to national bank branches"],[0,"(A) In general"],[2,"The laws of the host State regarding community reinvestment, consumer protection, fair lending, and establishment of intrastate branches shall apply to any branch in the host State of an out-of-State national bank to the same extent as such State laws apply to a branch of a bank chartered by that State, except—"],[3,"(i) when Federal law preempts the application of such State laws to a national bank; or"],[3,"(ii) when the Comptroller of the Currency determines that the application of such State laws would have a discriminatory effect on the branch in comparison with the effect the application of such State laws would have with respect to branches of a bank chartered by the host State."],[0,"(B) Enforcement of applicable State laws"],[2,"The provisions of any State law to which a branch of a national bank is subject under this paragraph shall be enforced, with respect to such branch, by the Comptroller of the Currency."],[0,"(C) Review and report on actions by Comptroller"],[2,"The Comptroller of the Currency shall conduct an annual review of the actions it has taken with regard to the applicability of State law to national banks (or their branches) during the preceding year, and shall include in its annual report required under section 14 of this title the results of the review and the reasons for each such action. The first such review and report after July 3, 1997, shall encompass all such actions taken on or after January 1, 1992."],[0,"(2) Treatment of branch as bank"],[1,"All laws of a host State, other than the laws regarding community reinvestment, consumer protection, fair lending, establishment of intrastate branches, and the application or administration of any tax or method of taxation, shall apply to a branch (in such State) of an out-of-State national bank to the same extent as such laws would apply if the branch were a national bank the main office of which is in such State."],[0,"(3) Rule of construction"],[1,"No provision of this subsection may be construed as affecting the legal standards for preemption of the application of State law to national banks."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/36?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§36. Branch banks","tname":"Banks and Banking","by":{"0":"52, 46, 11, 47, 47"}},{"t":"usc","label":"12 U.S.C. § 43","url":"https://www.law.cornell.edu/uscode/text/12/43","subs":["(a)"],"by":{"0":"25, 25"}},{"t":"usc","label":"12 U.S.C. § 92a","url":"https://www.law.cornell.edu/uscode/text/12/92a","subs":["(a)"],"by":{"0":"52"}},{"t":"usc","label":"12 U.S.C. § 1818","url":"https://www.law.cornell.edu/uscode/text/12/1818","subs":["(b)"],"by":{"0":"2, 54"}},{"t":"usc","label":"15 U.S.C. § 6711","url":"https://www.law.cornell.edu/uscode/text/15/6711","by":{"0":"47"}},{"t":"usc","label":"15 U.S.C. § 6714","url":"https://www.law.cornell.edu/uscode/text/15/6714","by":{"0":"25"}},{"t":"usc","label":"26 U.S.C. § 3305","url":"https://www.law.cornell.edu/uscode/text/26/3305","subs":["(c)"],"stext":{"head":"§3305. Applicability of State law","paras":[[0,"(a) Interstate and foreign commerce"],[0,"No person required under a State law to make payments to an unemployment fund shall be relieved from compliance therewith on the ground that he is engaged in interstate or foreign commerce, or that the State law does not distinguish between employees engaged in interstate or foreign commerce and those engaged in intrastate commerce."],[0,"(b) Federal instrumentalities in general"],[0,"The legislature of any State may require any instrumentality of the United States (other than an instrumentality to which section 3306(c)(6) applies), and the individuals in its employ, to make contributions to an unemployment fund under a State unemployment compensation law approved by the Secretary of Labor under section 3304 and (except as provided in section 5240 of the Revised Statutes, as amended (12 U.S.C., sec. 484), and as modified by subsection (c)), to comply otherwise with such law. The permission granted in this subsection shall apply (A) only to the extent that no discrimination is made against such instrumentality, so that if the rate of contribution is uniform upon all other persons subject to such law on account of having individuals in their employ, and upon all employees of such persons, respectively, the contributions required of such instrumentality or the individuals in its employ shall not be at a greater rate than is required of such other persons and such employees, and if the rates are determined separately for different persons or classes of persons having individuals in their employ or for different classes of employees, the determination shall be based solely upon unemployment experience and other factors bearing a direct relation to unemployment risk; (B) only if such State law makes provision for the refund of any contributions required under such law from an instrumentality of the United States or its employees for any year in the event such State is not certified by the Secretary of Labor under section 3304 with respect to such year; and (C) only if such State law makes provision for the payment of unemployment compensation to any employee of any such instrumentality of the United States in the same amount, on the same terms, and subject to the same conditions as unemployment compensation is payable to employees of other employers under the State unemployment compensation law."],[0,"(c) National banks"],[0,"Nothing contained in section 5240 of the Revised Statutes, as amended (12 U.S.C. 484), shall prevent any State from requiring any national banking association to render returns and reports relative to the association's employees, their remuneration and services, to the same extent that other persons are required to render like returns and reports under a State law requiring contributions to an unemployment fund. The Comptroller of the Currency shall, upon receipt of a copy of any such return or report of a national banking association from, and upon request of, any duly authorized official, body, or commission of a State, cause an examination of the correctness of such return or report to be made at the time of the next succeeding examination of such association, and shall thereupon transmit to such official, body, or commission a complete statement of his findings respecting the accuracy of such returns or reports."],[0,"(d) Federal property"],[0,"No person shall be relieved from compliance with a State unemployment compensation law on the ground that services were performed on land or premises owned, held, or possessed by the United States, and any State shall have full jurisdiction and power to enforce the provisions of such law to the same extent and with the same effect as though such place were not owned, held, or possessed by the United States."],[0,"[(e) Repealed. Sept. 1, 1954, ch. 1212, §4(c), 68 Stat. 1135]"],[0,"(f) American vessels"],[0,"The legislature of any State in which a person maintains the operating office, from which the operations of an American vessel operating on navigable waters within or within and without the United States are ordinarily and regularly supervised, managed, directed and controlled, may require such person and the officers and members of the crew of such vessel to make contributions to its unemployment fund under its State unemployment compensation law approved by the Secretary of Labor under section 3304 and otherwise to comply with its unemployment compensation law with respect to the service performed by an officer or member of the crew on or in connection with such vessel to the same extent and with the same effect as though such service was performed entirely within such State. Such person and the officers and members of the crew of such vessel shall not be required to make contributions, with respect to such service, to the unemployment fund of any other State. The permission granted by this subsection is subject to the condition that such service shall be treated, for purposes of wage credits given employees, like other service subject to such State unemployment compensation law performed for such person in such State, and also subject to the same limitation, with respect to contributions required from such person and from the officers and members of the crew of such vessel, as is imposed by the second sentence (other than clause (B) thereof) of subsection (b) with respect to contributions required from instrumentalities of the United States and from individuals in their employ."],[0,"(g) Vessels operated by general agents of United States"],[0,"The permission granted by subsection (f) shall apply in the same manner and under the same conditions (including the obligation to comply with all requirements of State unemployment compensation laws) to general agents of the Secretary of Transportation with respect to service performed by officers and members of the crew on or in connection with American vessels—"],[1,"(1) owned by or bareboat chartered to the United States, and"],[1,"(2) whose business is conducted by such general agents."],[0,"As to any such vessel, the State permitted to require contributions on account of such service shall be the State to which the general agent would make contributions if the vessel were operated for his own account. Such general agents are designated, for this purpose, instrumentalities of the United States neither wholly nor partially owned by it and shall not be exempt from the tax imposed by section 3301. The permission granted by this subsection is subject to the same conditions and limitations as are imposed in subsection (f), except that clause (B) of the second sentence of subsection (b) shall apply."],[0,"(h) Requirement by State of contributions"],[0,"Any State may, as to service performed on account of which contributions are made pursuant to subsection (g)—"],[1,"(1) require contributions from persons performing such service under its unemployment compensation law or temporary disability insurance law administered in connection therewith, and"],[1,"(2) require general agents of the Secretary of Transportation to make contributions under such temporary disability insurance law and to make such deductions from wages or remuneration as are required by such unemployment compensation or temporary disability insurance law."],[0,"(i) General agent as legal entity"],[0,"Each general agent of the Secretary of Transportation making contributions pursuant to subsection (g) or (h) shall, for purposes of such subsections, be considered a legal entity in his capacity as an instrumentality of the United States, separate and distinct from his identity as a person employing individuals on his own account."],[0,"(j) Denial of credits in certain cases"],[0,"Any person required, pursuant to the permission granted by this section, to make contributions to an unemployment fund under a State unemployment compensation law approved by the Secretary of Labor under section 3304 shall not be entitled to the credits permitted, with respect to the unemployment compensation law of a State, by subsections (a) and (b) of section 3302 against the tax imposed by section 3301 for any taxable year if, on October 31 of such taxable year, the Secretary of Labor certifies to the Secretary of the Treasury his finding, after reasonable notice and opportunity for hearing to the State agency, that the unemployment compensation law of such State is inconsistent with any one or more of the conditions on the basis of which such permission is granted or that, in the application of the State law with respect to the 12-month period ending on such October 31, there has been a substantial failure to comply with any one or more of such conditions. For purposes of section 3310, a finding of the Secretary of Labor under this subsection shall be treated as a finding under section 3304(c)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/3305?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3305. Applicability of State law","tname":"Internal Revenue Code","by":{"0":"36"}},{"t":"reg","label":"12 C.F.R. § 7.4000","url":"https://www.ecfr.gov/current/title-12/section-7.4000","by":{"0":"26"}}]};